const Range = struct { offset: usize, length: usize };

pub fn clip(state: State) Clip {
    return switch (state) {
        .ready => .{ .duration_ms = 5100, .repeat = true, .frames = &ready },
        .thinking => .{ .duration_ms = 620, .repeat = false, .frames = &thinking },
        .working => .{ .duration_ms = 3100, .repeat = true, .frames = &working },
        .waiting => .{ .duration_ms = 590, .repeat = false, .frames = &waiting },
        .blocked => .{ .duration_ms = 660, .repeat = false, .frames = &blocked },
        .done => .{ .duration_ms = 820, .repeat = false, .frames = &done },
    };
}

pub fn label(state: State) []const u8 {
    return switch (state) {
        .ready => "Ready",
        .thinking => "Thinking",
        .working => "Working",
        .waiting => "Waiting for you",
        .blocked => "Blocked",
        .done => "Finished",
    };
}

pub fn bytes(agent: Agent, pose: u8) []const u8 {
    const range = switch (agent) {
        .kai => kai[pose],
        .sol => sol[pose],
    };
